#!/usr/bin/env python3
"""Regenerate the static outline page from the reviewed, committed data."""
import json
from pathlib import Path
from html import escape as e
root = Path(__file__).resolve().parents[2]
data = json.loads((root / 'assets/notes/outlines.json').read_text(encoding='utf8'))
bs, chem = data['business_studies'], data['chemistry']
def card(c):
 im=('<figure><img loading="lazy" src="/'+e(c['image'])+'" alt="'+e(c['figure'])+'"><figcaption>NCERT figure '+e(c['fig'])+' · '+e(c['figure'])+' · PDF page '+str(c['page'])+' · source crop, not AI-drawn</figcaption></figure>') if 'image' in c else ''
 li=lambda a: ''.join('<li>'+e(x)+'</li>' for x in a)
 return '<article id="'+e(c['id'])+'"><div class="eyebrow">'+e(c['id']+'.pdf')+'</div><h3>'+e(c['title'])+'</h3><p>'+e(c['summary'])+'</p><div class="cols"><section><h4>Sections</h4><ul>'+li(c['sections'])+'</ul></section><section><h4>Objectives</h4><ul>'+li(c['objectives'])+'</ul></section></div><h4>Key terms</h4><p class="terms">'+e(' · '.join(c['terms']))+'</p>'+im+'</article>'
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Class 12 outlines | Upay</title><style>body{margin:0;background:#f6f5ef;color:#162b27;font:16px/1.6 system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:32px 22px 80px}a{color:#087357}header{padding:28px 0}h1{font-size:clamp(2rem,5vw,3.4rem);line-height:1.1;margin:12px 0}h2{margin:40px 0 10px;font-size:1.8rem}h3{font-size:1.4rem;margin:0 0 8px}h4{margin:12px 0 5px}article{scroll-margin-top:20px;background:white;border:1px solid #dbe5df;border-radius:16px;padding:24px;margin:16px 0;box-shadow:0 4px 18px #1428200c}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:#087357;font-weight:700}.notice{border-left:4px solid #d8a83b;background:#fff8e5;padding:16px 20px;border-radius:6px}.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:8px 32px}ul{padding-left:22px;margin:4px 0}.terms{color:#345c51}figure{margin:20px 0 0;border-top:1px solid #e1eae5;padding-top:16px}img{display:block;max-width:100%;max-height:320px;object-fit:contain;object-position:left}figcaption{font-size:13px;color:#52665e}nav a{display:inline-block;margin:4px 16px 4px 0}</style></head><body><main><a href="/">← Back to Upay</a><header><div class="eyebrow">CBSE · Class 12 · English · 2026–27</div><h1>Study outlines</h1><p>Short, syllabus-mapped study outlines, not full textbook chapters. Select a subject to begin.</p><nav><a href="#business">Business Studies</a><a href="#chemistry">Chemistry</a></nav></header><div class="notice"><strong>About verification.</strong> Topics were checked against the published CBSE 2026–27 syllabus, not certified by CBSE. These are concise study aids, not a complete syllabus, official notes or an answer key. Check your board and year. Any AI-generated questions are <strong>practice, not board-verified</strong>; none are included here.</div><h2 id="business">Business Studies</h2><p>11 source-derived outlines mapped to CBSE subject 054. The Financial Markets unit and project work are not included. <a href="https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/BusinessStudies_SecP2_2026-27.pdf">CBSE syllabus ↗</a></p><p class="notice"><strong>Consumer protection:</strong> CBSE prescribes the Consumer Protection Act, 2019. The staged source’s summary refers to the older 1986 Act; that conflicting excerpt is not reproduced here. The 2019 Act repeals the 1986 Act subject to savings (section 107). <a href="https://www.indiacode.nic.in/handle/123456789/15256">India Code ↗</a></p>'''+''.join(card(c) for c in bs)+'''<h2 id="chemistry">Chemistry</h2><p>Four chapters from the supplied NCERT reprint, mapped to CBSE subject 043. Chapters 5–10, practicals and project work are not in this batch. Figures are a selected sample, not a complete extraction. The two supplied answer appendices are not included. <a href="https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Chemistry_SecP2_2026-27.pdf">CBSE syllabus ↗</a></p>'''+''.join(card(c) for c in chem)+'''</main></body></html>'''
(root/'assets/notes/index.html').write_text(html)
